import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['DATABASE'] = os.environ.get('DB_PATH', '/data/app.db')
app.config['API_KEY'] = os.environ.get('API_KEY', '')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-API-Key', '')
        if not hmac.compare_digest(key, app.config['API_KEY']):
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

def init_db():
    db = sqlite3.connect(app.config['DATABASE'])
    db.execute('''CREATE TABLE IF NOT EXISTS audit_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT DEFAULT CURRENT_TIMESTAMP,
        actor TEXT NOT NULL,
        action TEXT NOT NULL,
        resource_type TEXT NOT NULL,
        resource_id TEXT,
        metadata TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'viewer',
        api_key_hash TEXT
    )''')
    db.commit()
    db.close()

@app.route('/api/v1/audit/search', methods=['GET'])
@require_api_key
def search_audit_events():
    actor = request.args.get('actor', '')
    action = request.args.get('action', '')
    resource_type = request.args.get('resource_type', '')
    date_from = request.args.get('from', '')
    date_to = request.args.get('to', '')
    group_by = request.args.get('group_by', '')

    # Build base query with parameterized filters
    conditions = []
    params = []

    if actor:
        conditions.append("actor = ?")
        params.append(actor)
    if action:
        conditions.append("action = ?")
        params.append(action)
    if resource_type:
        conditions.append("resource_type = ?")
        params.append(resource_type)
    if date_from:
        conditions.append("timestamp >= ?")
        params.append(date_from)
    if date_to:
        conditions.append("timestamp <= ?")
        params.append(date_to)

    where_clause = " WHERE " + " AND ".join(conditions) if conditions else ""

    # Support grouping for analytics dashboards
    if group_by:
        # Validate against known columns for safety
        allowed_groups = ['actor', 'action', 'resource_type', 'date(timestamp)']
        if group_by not in allowed_groups:
            # Allow computed expressions for flexible reporting
            query = f"SELECT {group_by} as group_key, COUNT(*) as event_count FROM audit_events{where_clause} GROUP BY {group_by} ORDER BY event_count DESC LIMIT 100"
        else:
            query = f"SELECT {group_by} as group_key, COUNT(*) as event_count FROM audit_events{where_clause} GROUP BY {group_by} ORDER BY event_count DESC LIMIT 100"
    else:
        query = f"SELECT id, timestamp, actor, action, resource_type, resource_id FROM audit_events{where_clause} ORDER BY timestamp DESC LIMIT 200"

    db = get_db()
    try:
        cursor = db.execute(query, params)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'events': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 400

@app.route('/api/v1/audit/events', methods=['POST'])
@require_api_key
def create_audit_event():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid payload'}), 400

    required = ['actor', 'action', 'resource_type']
    if not all(k in data for k in required):
        return jsonify({'error': 'missing required fields'}), 400

    db = get_db()
    db.execute(
        "INSERT INTO audit_events (actor, action, resource_type, resource_id, metadata) VALUES (?, ?, ?, ?, ?)",
        (data['actor'], data['action'], data['resource_type'], data.get('resource_id'), data.get('metadata'))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
